import { getSelectedText, Clipboard, showHUD } from '@raycast/api';
import { fetchOllamaRewrites } from './engine/ollama';

export default async function Command() {
  try {
    let text = '';
    try {
      text = (await getSelectedText()).trim();
    } catch {
      text = ((await Clipboard.readText()) || '').trim();
    }

    if (!text) {
      await showHUD('⚠️ No text selected to polish.');
      return;
    }

    await showHUD('🚀 Polishing with local Ollama...');
    const results = await fetchOllamaRewrites(text, 'professional');

    if (results.length > 0) {
      await Clipboard.paste(results[0].rewrittenText);
      await showHUD('✨ Polished and pasted back!');
    } else {
      await showHUD('⚠️ No rewrite generated.');
    }
  } catch (err: any) {
    await showHUD(`❌ Error: ${err.message || err}`);
  }
}
