/**
 * Fast deterministic rules for quick cleanups
 */
export function applyFastFixes(text: string): string {
  let res = text;
  // 1. Remove repeated consecutive duplicate words
  res = res.replace(/\b([a-zA-Z]{2,})\s+\1\b/gi, '$1');
  // 2. Fix typography
  res = res.replace(/--/g, '—');
  res = res.replace(/\.{3}/g, '…');
  res = res.replace(/(^|[\s])"([a-zA-Z0-9])/g, '$1“$2');
  res = res.replace(/([a-zA-Z0-9.,!?;:])"/g, '$1”');
  // 3. Redundant spaces
  res = res.replace(/[ \t]{2,}/g, ' ');
  return res.trim();
}
