export function generateDiffMarkdown(original: string, rewritten: string): string {
  const origWords = original.split(/\s+/).filter(Boolean);
  const newWords = rewritten.split(/\s+/).filter(Boolean);

  // Simple clean diff markdown presentation
  return `### Original:
> ${original}

### Polished (${newWords.length} words):
> **${rewritten}**

---
*Generated with local Ollama • 100% private*`;
}
