import { getPreferenceValues } from '@raycast/api';
import { Tone, RewriteChoice } from '../types';
import { generateDiffMarkdown } from './diff';
import { applyFastFixes } from './deterministic';

interface Preferences {
  ollamaHost?: string;
  ollamaModel?: string;
}

export async function fetchOllamaRewrites(originalText: string, activeTone?: Tone): Promise<RewriteChoice[]> {
  const prefs = getPreferenceValues<Preferences>();
  const host = (prefs.ollamaHost || 'http://localhost:11434').replace(/\/v1\/?$/, '');
  const model = prefs.ollamaModel || 'qwen2.5vl:latest';

  const toneInstructions: Record<Tone, string> = {
    professional: 'Polished, formal, and articulate for professional communication.',
    casual: 'Relaxed, conversational, friendly, and approachable.',
    academic: 'Rigorous, scholarly, and articulate with elevated vocabulary.',
    confident: 'Assertive, direct, and authoritative without weak qualifiers.',
    shorten: 'Extremely concise, tight, cutting all fluff and filler.',
    expand: 'Rich in detail, descriptive nuance, and thorough explanation.',
    natural: 'Natural, fluid, and clear phrasing.',
  };

  const selectedTone = activeTone || 'professional';
  const prompt = `Rewrite the following text into 3 distinct, high-quality variations.
Text: "${originalText.trim()}"
Style: ${toneInstructions[selectedTone]}
Output ONLY a JSON array of 3 strings. Example: ["Variation 1", "Variation 2", "Variation 3"]`;

  try {
    const res = await fetch(`${host}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: 'You are a concise sentence rewriting assistant. Output ONLY a valid JSON array of 3 strings.' },
          { role: 'user', content: prompt },
        ],
        temperature: 0.7,
        max_tokens: 500,
      }),
    });

    if (!res.ok) {
      throw new Error(`Ollama HTTP ${res.status}`);
    }

    const data: any = await res.json();
    let raw = data.choices?.[0]?.message?.content || '[]';

    // Strip thinking tags or markdown fences
    if (raw.includes('</think>')) {
      raw = raw.split('</think>')[1].trim();
    }
    if (raw.startsWith('```')) {
      const lines = raw.split('\n');
      raw = lines.slice(1, -1).join('\n').trim();
    }

    let parsed: string[] = [];
    try {
      parsed = JSON.parse(raw);
    } catch {
      parsed = raw
        .split('\n')
        .map((l: string) => l.replace(/^[\d.\-* ]+/, '').replace(/^["']|["']$/g, '').trim())
        .filter(Boolean);
    }

    const choices: RewriteChoice[] = parsed.slice(0, 4).map((text, idx) => ({
      id: `ollama-${idx}`,
      tone: selectedTone,
      label: `${selectedTone.toUpperCase()} Variation ${idx + 1}`,
      rewrittenText: text.trim(),
      originalText: originalText.trim(),
      diffMarkdown: generateDiffMarkdown(originalText, text.trim()),
    }));

    if (choices.length === 0) {
      const fallback = applyFastFixes(originalText);
      return [
        {
          id: 'fallback-1',
          tone: selectedTone,
          label: 'Polished Text',
          rewrittenText: fallback,
          originalText,
          diffMarkdown: generateDiffMarkdown(originalText, fallback),
        },
      ];
    }

    return choices;
  } catch (err: any) {
    const fallback = applyFastFixes(originalText);
    return [
      {
        id: 'error-fallback',
        tone: selectedTone,
        label: 'Local Heuristic Cleaned (Ollama Offline)',
        rewrittenText: fallback,
        originalText,
        diffMarkdown: `> ⚠️ **Ollama notice**: ${err.message || 'Cannot reach localhost:11434'}. Showing local rule-cleaned variation.\n\n${generateDiffMarkdown(originalText, fallback)}`,
      },
    ];
  }
}
